#include "../glove_cosmetics.h"
#include <cassert>
#include <iostream>
using C=cs2_live::GloveCosmetics;using Json=nlohmann::json;
static std::uint32_t Bits(float f){std::uint32_t b=0;std::memcpy(&b,&f,4);return b;}
static Json Attr(unsigned id,float f){return {{"definition",id},{"value_bits",Bits(f)},{"initial_bits",Bits(f)},{"refundable",0},{"set_bonus",0}};}
static Json Item(unsigned def=5030){return {{"m_iItemDefinitionIndex",def},{"m_bInitialized",1},{"m_iItemID",0},{"m_iItemIDHigh",12},{"m_iItemIDLow",34},{"m_iEntityQuality",3},{"m_iEntityLevel",1},{"m_iAccountID",123},{"m_szCustomName","Original custom glove"},{"m_szCustomNameOverride","baseline override"},{"attributes",Json::array({Attr(6,10006.f),Attr(8,0.3f),Attr(80,4.f)})},{"network_attributes",Json::array({Attr(7,13.f)})}};}
struct Engine {
    std::vector<C::Glove> live;unsigned writes=0,captures=0,restores=0,destroyed=0;bool rejectSnapshot=false,rejectApply=false,rejectRestore=false,expire=false,hidden=false,partialFailure=false;
    Engine(){for(unsigned i=0;i<2;++i){C::Glove g;g.actor.steamId=std::to_string(76561198012345678ull+i);g.actor.nickname="same nickname";g.actor.team=2+i;g.actor.instance=0x1000+i*0x1000;g.actor.pawnHandle=32775+i;g.actor.controllerHandle=65540+i;g.actor.generation=1;g.item=Item();g.itemDef=5030;g.itemReadable=g.ready=g.worldReady=g.hudReady=g.worldPoseReady=g.hudPoseReady=g.worldRenderReady=g.hudRenderReady=true;g.hudParentRenderEnabled=true;g.worldMaterialJobs=g.hudMaterialJobs=0;live.push_back(g);}}
    bool Current(const C::Glove& g)const{if(expire)return false;for(const auto& a:live)if(a.actor.instance==g.actor.instance && a.actor.pawnHandle==g.actor.pawnHandle && a.actor.steamId==g.actor.steamId && a.actor.controllerHandle==g.actor.controllerHandle && a.actor.generation==g.actor.generation)return true;return false;}
    C::Callbacks Callbacks(){C::Callbacks cb;cb.available=true;cb.reason="simulated engine";cb.gloves=[&]{return hidden?std::vector<C::Glove>{}:live;};cb.current=[&](const auto& g){return Current(g);};cb.resolve=[](const Json& j){C::Paint p;p.itemDef=j["item_def"].get<unsigned>();p.kit=j["paint_kit"].get<unsigned>();if((p.itemDef!=5030 && p.itemDef!=5035) || (p.kit!=10006 && p.kit!=10007))throw std::invalid_argument("not a builtin glove pair");p.seed=j.value("seed",0u);p.wear=j.value("wear",0.01f);return p;};
        cb.snapshot=[&](const C::Glove& g)->std::shared_ptr<C::Snapshot>{assert(Current(g));++captures;if(rejectSnapshot)return {};auto s=std::make_shared<C::Snapshot>();s->item=g.item;s->native=std::shared_ptr<void>(new int(1),[&](void* p){delete static_cast<int*>(p);++destroyed;});return s;};
        cb.apply=[&](const C::Glove& g,const C::Paint& p){assert(Current(g));++writes;if(rejectApply && !partialFailure)return false;for(auto& a:live)if(a.actor.instance==g.actor.instance){a.item["m_iItemDefinitionIndex"]=p.itemDef;a.item["m_bInitialized"]=1;a.item["m_iItemIDHigh"]=0;a.item["m_iItemIDLow"]=0;a.item["m_szCustomName"]="";a.item["attributes"]=Json::array({Attr(6,float(p.kit)),Attr(7,float(p.seed)),Attr(8,p.wear)});a.itemDef=p.itemDef;}return !rejectApply;};
        cb.restore=[&](const C::Glove& g,const C::Snapshot& s){assert(Current(g));++restores;if(rejectRestore)return false;for(auto& a:live)if(a.actor.instance==g.actor.instance){a.item=s.item;a.itemDef=s.item["m_iItemDefinitionIndex"].get<unsigned>();}return true;};return cb;}
    Json Desired(unsigned def=5035,unsigned kit=10006)const{return Json::array({{{"steam_id",live[0].actor.steamId},{"nickname","same nickname"},{"item_def",def},{"paint_kit",kit},{"seed",42},{"wear",0.1}}});}
};
template<class Fn>static void Reject(Fn fn){bool failed=false;try{fn();}catch(const std::exception&){failed=true;}assert(failed);}
static void ScopeAndExactReset(){Engine e;C c;c.Bind(e.Callbacks());const auto original=e.live[0].item,other=e.live[1].item;c.ValidateRequest(e.Desired(),true);c.Apply(e.Desired());assert(e.captures==1 && e.writes==1 && e.live[1].item==other && c.State()["gloves"][0]["applied"]==true);assert(c.State()["gloves"][1]["applied"]==false);c.Refresh(true);assert(e.writes==1 && e.captures==1);c.Apply(Json::array());assert(e.restores==1 && e.live[0].item==original && e.live[1].item==other && e.destroyed==1 && c.State()["owned_overrides"]==0);assert(c.Capabilities()["render_verified_1p"]==false && c.Capabilities()["render_verified_3p"]==false);}
static void SnapshotRejectAndBoundedFailures(){Engine e;C c;e.rejectSnapshot=true;c.Bind(e.Callbacks());c.Apply(e.Desired());c.Refresh(true);c.Refresh(true);assert(e.captures==1 && e.writes==0 && c.State()["owned_overrides"]==0);e.rejectSnapshot=false;c.Apply(e.Desired(5035,10007));assert(e.writes==1 && e.captures==2);e.rejectRestore=true;c.Apply(Json::array());c.Refresh(false);c.Refresh(false);assert(e.restores==1 && c.State()["owned_overrides"]==1);e.rejectRestore=false;c.Apply(e.Desired(5030));c.Apply(Json::array());assert(c.State()["owned_overrides"]==0);}
static void ApplyRejectAndPartialReset(){Engine e;C c;e.rejectApply=true;c.Bind(e.Callbacks());const auto original=e.live[0].item;c.Apply(e.Desired());c.Refresh(true);assert(e.writes==1 && c.State()["gloves"][0]["applied"]==false);c.Apply(Json::array());assert(e.live[0].item==original);e.partialFailure=true;c.Apply(e.Desired());assert(e.live[0].item!=original && c.State()["gloves"][0]["applied"]==false);c.Apply(Json::array());assert(e.live[0].item==original);}
static void ReusedLifetimeNeverRestores(){Engine e;C c;c.Bind(e.Callbacks());c.Apply(e.Desired());e.live[0].actor.pawnHandle+=32768;e.live[0].actor.instance+=0x10000;e.live[0].item=Item(5032);c.Refresh(false);assert(e.restores==0 && e.destroyed==1 && e.live[0].item==Item(5032) && c.State()["owned_overrides"]==0);c.Apply(e.Desired());e.live.erase(e.live.begin());++e.live[0].actor.generation;c.Refresh(false);assert(e.restores==0 && c.State()["owned_overrides"]==0);}
static void NetworkBaselineDoesNotClobber(){Engine e;C c;c.Bind(e.Callbacks());c.Apply(e.Desired());auto network=Item(5030);network["m_szCustomName"]="Network seek baseline";e.live[0].item=network;++e.live[0].networkVersion;c.Refresh(false);assert(e.restores==0 && e.live[0].item==network && c.State()["owned_overrides"]==0);c.Apply(e.Desired());c.Apply(Json::array());assert(e.live[0].item==network);c.Apply(e.Desired());++e.live[0].networkVersion;c.Apply(Json::array());assert(e.restores==2 && e.live[0].item==network && c.State()["owned_overrides"]==0);}
static void ReadbackReadinessAndMissingSnapshot(){Engine e;C c;c.Bind(e.Callbacks());c.Apply(e.Desired());e.live[0].worldMaterialJobs=1;e.live[0].hudMaterialJobs=2;c.Refresh(true);assert(c.State()["gloves"][0]["applied"]==true && c.State()["gloves"][0]["materials_pending"]==true);e.live[0].ready=false;e.live[0].worldMaterialJobs=0;e.live[0].hudMaterialJobs=0;c.Refresh(true);assert(c.State()["gloves"][0]["applied"]==true && c.State()["gloves"][0]["ready"]==false);e.hidden=true;c.Refresh(false);assert(c.State()["owned_overrides"]==1 && e.restores==0);e.hidden=false;e.live[0].ready=true;c.Refresh(false);assert(e.restores==1);}
static void TeamChangePreservesOriginal(){Engine e;C c;c.Bind(e.Callbacks());const auto original=e.live[0].item;c.Apply(e.Desired());e.live[0].actor.team=3;c.Refresh(true);assert(e.captures==1 && e.writes==1 && c.State()["owned_overrides"]==1);c.Apply(Json::array());assert(e.live[0].item==original && e.restores==1 && e.destroyed==1);}
static void SelectionAndCachesPreserveOriginal(){Engine e;C c;c.Bind(e.Callbacks());const auto original=e.live[0].item;c.Apply(e.Desired());c.Apply(e.Desired(5030,10007));assert(e.captures==1 && e.writes==2);e.live[0].item["m_bInitializedTags"]=1;e.live[0].item["m_szCurrentLoadCachedFileName"]="lazy-cache-populated";++e.live[0].networkVersion;c.Refresh(true);assert(e.captures==1 && e.writes==2 && c.State()["gloves"][0]["applied"]==true);c.Apply(Json::array());assert(e.live[0].item==original && e.restores==1);}
static void NativeCopyIdContract(){Engine e;C c;auto cb=e.Callbacks();const auto original=e.live[0].item;const auto saved=cb.snapshot;cb.snapshot=[saved](const C::Glove& g){auto result=saved(g);if(result)result->item=C::CopyCanonical(result->item);return result;};c.Bind(cb);c.Apply(e.Desired());assert(e.writes==1 && e.captures==1);c.Apply(Json::array());assert(e.live[0].item!=original && C::Semantic(e.live[0].item)==C::Semantic(original));assert(e.live[0].item["m_iItemID"]==((std::uint64_t(12)<<32)|34));assert(c.State()["gloves"][0]["raw_item_id"]==c.State()["gloves"][0]["engine_copy_item_id"]);e.live[0].item["m_iItemID"]=123456789;c.Apply(e.Desired());assert(e.writes==1 && e.captures==1 && c.State()["gloves"][0].contains("error"));}
static void UnreadableSnapshotRetainsJournal(){Engine e;C c;c.Bind(e.Callbacks());const auto baseline=e.live[0].item;c.Apply(e.Desired());const auto owned=e.live[0].item;e.live[0].itemReadable=e.live[0].ready=false;e.live[0].item=Json::object();c.Refresh(false);assert(e.restores==0 && e.destroyed==0 && c.State()["owned_overrides"]==1);e.live[0].item={{"m_iItemDefinitionIndex",5035}};c.Refresh(false);assert(e.restores==0 && e.destroyed==0 && c.State()["owned_overrides"]==1);e.live[0].item=owned;e.live[0].itemReadable=e.live[0].ready=true;c.Refresh(false);assert(e.restores==1 && e.live[0].item==baseline && e.destroyed==1 && c.State()["owned_overrides"]==0);}
static void PostWriteUnreadableRetainsJournal(){for(bool partial:{false,true}){Engine e;C c;auto cb=e.Callbacks();const auto baseline=e.live[0].item;unsigned reads=0;cb.gloves=[&]{auto result=e.live;if(++reads==2){result[0].itemReadable=result[0].ready=false;result[0].item=partial?Json{{"m_iItemDefinitionIndex",5035}}:Json::object();}return result;};c.Bind(cb);c.Apply(e.Desired());assert(e.writes==1 && e.captures==1 && e.destroyed==0 && c.State()["gloves"][0]["restoration_unresolved"]==true && c.State()["restoration_unresolved"]==true && c.State()["gloves"][0]["applied"]==false);c.Refresh(true);c.Apply(Json::array());assert(e.writes==1 && e.captures==1 && e.restores==0 && e.destroyed==0 && c.State()["owned_overrides"]==1);e.live[0].item=baseline;e.live[0].itemDef=5030;c.Refresh(false);assert(e.restores==1 && e.destroyed==1 && c.State()["owned_overrides"]==0);}}
static void PostWriteReadableModelPending(){Engine e;C c;auto cb=e.Callbacks();const auto apply=cb.apply;const auto baseline=e.live[0].item;cb.apply=[&](const C::Glove& g,const C::Paint& p){const bool result=apply(g,p);e.live[0].ready=e.live[0].worldReady=e.live[0].hudReady=false;e.live[0].worldMaterialJobs=1;return result;};c.Bind(cb);c.Apply(e.Desired());assert(c.State()["gloves"][0]["applied"]==true && c.State()["gloves"][0]["ready"]==false && c.State()["gloves"][0]["restoration_unresolved"]==false && c.State()["gloves"][0]["materials_pending"]==true);c.Apply(Json::array());assert(e.restores==0 && e.captures==1 && e.destroyed==0 && c.State()["owned_overrides"]==1);e.live[0].ready=e.live[0].worldReady=e.live[0].hudReady=true;e.live[0].worldMaterialJobs=0;c.Refresh(false);assert(e.restores==1 && e.live[0].item==baseline && e.destroyed==1);}
static void ValidationAndSteamScope(){Engine e;C c;c.Bind(e.Callbacks());auto j=e.Desired();j.push_back(j[0]);j[1]["item_def"]=5030;Reject([&]{c.ValidateRequest(j);});for(const auto& bad:std::vector<std::pair<std::string,Json>>{{"steam_id",123},{"seed",true},{"wear",true},{"item_def",5035.0},{"paint_kit",0},{"address",123}}){j=e.Desired();j[0][bad.first]=bad.second;Reject([&]{c.ValidateRequest(j);});}j=e.Desired();j[0]["steam_id"]="76561198012345670";Reject([&]{c.ValidateRequest(j,true);});j=e.Desired();j[0]["item_def"]=7;Reject([&]{c.ValidateRequest(j);});C missing;Reject([&]{missing.Apply(e.Desired());});assert(e.writes==0);}
static void PosePendingDoesNotRecaptureOwnedItem(){Engine e;C c;const auto baseline=e.live[0].item;c.Bind(e.Callbacks());c.Apply(e.Desired());e.live[0].worldPoseReady=false;c.Refresh(true);assert(c.State()["gloves"][0]["applied"]==true && c.State()["gloves"][0]["world_pose_ready"]==false && c.State()["gloves"][0]["materials_pending"]==true);e.live[0].worldPoseReady=true;e.live[0].hudPoseReady=false;c.Refresh(true);assert(c.State()["gloves"][0]["materials_pending"]==true);e.live[0].hudPoseReady=true;e.live[0].worldRenderReady=false;c.Refresh(true);assert(c.State()["gloves"][0]["materials_pending"]==true);e.live[0].worldRenderReady=true;e.live[0].hudRenderReady=false;c.Refresh(true);assert(c.State()["gloves"][0]["materials_pending"]==true);e.live[0].hudParentRenderEnabled=false;e.live[0].hudRenderRequired=false;c.Refresh(true);assert(c.State()["gloves"][0]["materials_pending"]==false && c.State()["gloves"][0]["hud_render_ready"]==false && c.State()["gloves"][0]["hud_parent_render_enabled"]==false && e.writes==1 && e.captures==1);e.live[0].hudParentRenderEnabled=true;e.live[0].hudRenderRequired=true;c.Refresh(true);assert(c.State()["gloves"][0]["materials_pending"]==true);e.live[0].hudRenderReady=true;c.Refresh(true);assert(c.State()["gloves"][0]["materials_pending"]==false && e.writes==1 && e.captures==1);c.Apply(Json::array());assert(e.restores==1 && e.live[0].item==baseline);}
static void LateObservationDoesNotMutateJournal(){Engine e;std::function<void()> observe;{C c;auto callbacks=e.Callbacks();callbacks.observe=[&]{return e.live;};callbacks.observeAfterRender=[&](std::function<void()> f){observe=std::move(f);};c.Bind(std::move(callbacks));c.Context(true,123,true);c.Apply(e.Desired());assert(observe && e.writes==1 && e.captures==1);e.live[0].worldRenderReady=false;observe();assert(c.State()["gloves"][0]["materials_pending"]==true && c.State()["gloves"][0]["applied"]==true);++e.live[0].networkVersion;observe();assert(c.State()["gloves"][0]["applied"]==false && c.State()["owned_overrides"]==1 && e.writes==1 && e.restores==0);--e.live[0].networkVersion;e.live[0].worldRenderReady=true;observe();assert(c.State()["gloves"][0]["materials_pending"]==false && c.State()["gloves"][0]["applied"]==true);c.Apply(Json::array());assert(e.restores==1);}observe();assert(e.writes==1 && e.restores==1);}
static void BackendRegistrationIsTransactional(){
    Engine first,second;unsigned firstReads=0,secondReads=0,registrations=0;
    std::function<void()> firstObserver,failedObserver,secondObserver;
    {
        C c;auto initial=first.Callbacks();initial.reason="first backend";
        initial.observe=[&]{++firstReads;return first.live;};
        initial.observeAfterRender=[&](std::function<void()> f){firstObserver=std::move(f);};
        c.Bind(std::move(initial));firstObserver();assert(firstReads==1);
        auto rejected=second.Callbacks();rejected.reason="rejected backend";
        rejected.observe=[&]{++secondReads;return second.live;};
        rejected.observeAfterRender=[&](std::function<void()> f){++registrations;failedObserver=std::move(f);failedObserver();throw std::runtime_error("registration rejected");};
        Reject([&]{c.Bind(rejected);});
        assert(registrations==1 && firstReads==1 && secondReads==0 && c.Capabilities()["reason"]=="first backend");
        failedObserver();firstObserver();assert(firstReads==2 && secondReads==0);
        c.Apply(first.Desired());assert(first.writes==1 && c.State()["owned_overrides"]==1);
        // Reject ownership before a candidate can replace the native observer.
        Reject([&]{c.Bind(rejected);});assert(registrations==1);
        c.Apply(Json::array());assert(first.restores==1 && c.State()["owned_overrides"]==0);
        auto replacement=second.Callbacks();replacement.reason="second backend";
        replacement.observe=[&]{++secondReads;return second.live;};
        replacement.observeAfterRender=[&](std::function<void()> f){++registrations;secondObserver=std::move(f);secondObserver();};
        c.Bind(std::move(replacement));
        assert(registrations==2 && firstReads==2 && secondReads==0 && c.Capabilities()["reason"]=="second backend");
        firstObserver();failedObserver();assert(firstReads==2 && secondReads==0);
        secondObserver();assert(secondReads==1);
        c.Apply(second.Desired());c.Apply(Json::array());assert(second.writes==1 && second.restores==1);
    }
    firstObserver();failedObserver();secondObserver();assert(firstReads==2 && secondReads==1);
}
int main(){BackendRegistrationIsTransactional();LateObservationDoesNotMutateJournal();ScopeAndExactReset();SnapshotRejectAndBoundedFailures();ApplyRejectAndPartialReset();ReusedLifetimeNeverRestores();NetworkBaselineDoesNotClobber();ReadbackReadinessAndMissingSnapshot();ValidationAndSteamScope();TeamChangePreservesOriginal();SelectionAndCachesPreserveOriginal();NativeCopyIdContract();UnreadableSnapshotRetainsJournal();PostWriteUnreadableRetainsJournal();PostWriteReadableModelPending();PosePendingDoesNotRecaptureOwnedItem();std::cout<<"glove cosmetics tests passed\n";}
